#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

int main(void) {
    pid_t pid = fork();
    if (pid == 0) {              /* child */
        exit(7);                 /* dies at once */
    }
    sleep(1);                    /* parent does not wait yet */
    char cmd[64];
    snprintf(cmd, sizeof cmd, "ps -o pid=,stat= -p %d", (int)pid);
    system(cmd);                 /* child shows as Z */
    int status;
    waitpid(pid, &status, 0);    /* reap: collect exit status */
    printf("reaped %d, exit status %d\n", (int)pid, WEXITSTATUS(status));
    system(cmd);                 /* now gone: prints nothing */
    return 0;
}

#define _GNU_SOURCE
#include <sched.h>
#include <stdio.h>
#include <time.h>
#include <unistd.h>
#define N 10000

static double now(void) {
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec / 1e9;
}

int main(void) {
#ifdef __linux__
    cpu_set_t one;                     /* both processes on CPU 0 */
    CPU_ZERO(&one); CPU_SET(0, &one);
    sched_setaffinity(0, sizeof one, &one);   /* inherited by fork */
#endif
    char b = 'x';
    int ab[2], ba[2], self[2];
    pipe(ab); pipe(ba); pipe(self);

    /* t2: N simulated round trips, one write + one read, no switch */
    double s = now();
    for (int i = 0; i < N; i++) {
        write(self[1], &b, 1); read(self[0], &b, 1);
    }
    double t2 = now() - s;

    /* t1: ping-pong, every read blocks until the other side writes */
    if (fork() == 0) {
        for (int i = 0; i < N; i++) {
            read(ab[0], &b, 1); write(ba[1], &b, 1);
        }
        _exit(0);
    }
    s = now();
    for (int i = 0; i < N; i++) {
        write(ab[1], &b, 1); read(ba[0], &b, 1);
    }
    double t1 = now() - s;

    printf("t1 = %.1f ms, t2 = %.1f ms\n", t1 * 1e3, t2 * 1e3);
    printf("c1 = %.2f us per switch\n", (t1 / (2.0 * N) - t2 / N) * 1e6);
    return 0;
}

