#include <stdio.h>
#include <ucontext.h>

static ucontext_t main_ctx, co_ctx;
static char co_stack[16384];

static void coroutine(void) {
    printf("co: step 1\n");
    swapcontext(&co_ctx, &main_ctx);   /* yield to main */
    printf("co: step 2\n");
}                                      /* return: go to uc_link */

int main(void) {
    getcontext(&co_ctx);
    co_ctx.uc_stack.ss_sp = co_stack;
    co_ctx.uc_stack.ss_size = sizeof co_stack;
    co_ctx.uc_link = &main_ctx;
    makecontext(&co_ctx, coroutine, 0);

    printf("main: start co\n");
    swapcontext(&main_ctx, &co_ctx);
    printf("main: co yielded\n");
    swapcontext(&main_ctx, &co_ctx);
    printf("main: co finished\n");
    return 0;
}
